namespace Lifestone.Client.Options;

public static partial class OptionCatalog
{
    /// <summary>
    /// Play mode in the main scene: the session host and its checks (M2 wave-2 track G6; parsed by
    /// src/Lifestone.Client/Play/PlayOptions.cs). The play switch itself, <c>--play</c>, is the <see cref="Session"/> group's.
    /// </summary>
    public static OptionGroup Play() => new("Play mode", "main scene",
    [
        new("--login-check", "enter", "Run an automated login check on the bundled ACE and quit (0 = it held; implies --play; tools\\play.ps1 -Offscreen runs it on the test account): 'enter' is the whole first-login path, off-screen: the data check, the character list, select (or create 'Lifestone Smoke'), Enter, portal space, the arrival in the Training Academy, LoginComplete once, the unhide, a 5 s wait, a log off back to the character list and quit. The frame rule is judged: the run fails on any frame over 50 ms between Enter and walking (the first 3 frames after the character list appears are excluded: building that screen is the retail UI's own cost). An automated run uses only the test account: with no --account it is accounts.test, and any other --account is refused. The longer checks play movement scenarios with the game's own player between the settle and the log off, on the live server: 'academy-exit' walks to the Academy's exit portal and uses it (the server walks the player the rest of the way), 'holtburg-laps' is sent to Holtburg by a server teleport and walks three laps of a ring around its arrival point, and 'all' (also the bare --login-check) is the enter path, then the Academy exit, then the Holtburg laps, in one login. Each ends with the character back at its start; ACE must accept every move (no force-position correction, where-am-I within 0.5 m at every stop). The Academy's exit portal is quest-gated in ACE's world database: the leg asks the server mod for the Sentry's quest, stamps it when the character lacks it, uses the portal (ACE teleports the character to Holtburg: exit=teleported, required), and after the way home asks the registry and puts the quest back as it found it (the portal's own emote set erases it, so a quest found held is stamped again). The portal's emote set also graduates the character for good: its sanctuary moves to Holtburg, recalls are enabled and ten Academy quests are erased, and nothing puts those back (the run leaves the character's position and that one quest as found, nothing else). Prints '[logincheck] done ok=<true|false> enter_to_walk_max_ms=<x> holtburg_min_fps=<x|n/a> corrections=<n|n/a> where_max_m=<x|n/a> exit=<teleported|failed|n/a> quest=<put-back|unchanged|unverified|n/a> legs=<names|none> teleports=<n> leg_teleports=<n> teleport_frame_max_ms=<x|n/a> academy_objects=<n> logoff=<ok|failed> materialised=<true|false|n/a> fade_ms=<ms|n/a> objects_drawn=<n|n/a>' (materialised: the server created the player hidden, unhid it, its body was drawn and its own Hidden-script particles were drawn; fade_ms: the player's materialise fade measured on frames, from the first visible frame after the unhide to the first opaque one, judged between 650 and 900 ms around the UnHide script's 750 ms hook, through at least five frames of intermediate alpha, never opaque before the fade; holtburg_min_fps: the slowest one-second window of the Holtburg laps, judged against 60; teleport_frame_max_ms: the longest frame from a leg's server teleport to a second after the player is present again, judged against 50). 'throwaway' is a separate check, never part of 'all' (D59, D61, D65): it creates 'Lifestone Throwaway' on the test account through the retail character-creation screens (first trying the taken name 'Lifestone Smoke' and a creature's name, which ACE refuses in retail dialogs), enters the world at once, uses the tools panel (Where am I, Add XP 2,500 to that character only, a Places teleport to Holtburg), logs off, deletes it with the typed word, restores it, deletes it again, then enters 'Lifestone Smoke', purges the throwaway with the server mod's char purge verb and logs off, so the account ends as it began (a throwaway left by a failed run is deleted and purged first and reported as leftover=yes). Prints '[logincheck] throwaway done ok=<true|false> throwaway=<purged|failed> name_errors=<n> xp=<added|n/a> where_m=<m|n/a> place=<teleported|n/a> deletes=<n> restores=<n> list=<same|different|n/a> leftover=<yes|no> enter_to_walk_max_ms=<x|n/a> teleport_frame_max_ms=<x|n/a>' and needs the server mod installed with the purge verb. Run it with tools\\godot.ps1 -TimeoutSeconds 840 (the leg aborts itself at 600 s and allows 120 s more to recover).", OptionRole.CheckSuite),
        new("--play-frames", "DIR", "With --play-checks: save the shell's review frames (the arrival, portal space in the SmartBox, an object selected, a NotInM2 message, character information, the options with side-by-side vitals, the logout confirmation) to DIR (default docs/screenshots/m2/shell/<W>x<H>), fail on a missing, blank or wrong-sized frame, and print 'shell frames done'. The frame-time judgement is reported, not judged (the read-back stalls frames). The frames are derived from the dats and never committed.", ValueOptional: true),
        new("--retail-picking", null, "Retail's picking rules where Lifestone fixes them (default: the nearest polygon of a part, hit times in world units): a part's first hit polygon in its own order, and hit times compared in each part's own scaled local-ray units, which can pick a different object than the nearest one under the pointer (docs/avatars.md section 18)."),
        new("--retail-unhide-flash", null, "Retail's one opaque frame when an object or the player is unhidden after a re-hide in the middle of its materialise fade (default: that frame is not drawn; the new fade starts at full translucency): retail's older fade hook leaves translucency 0 behind while the object is hidden and the unhide's own fade hook applies a frame later (docs/avatars.md section 17)."),
        new("--all-sizes", null, "With --retail-ui-checks: also place the shell at 1920x1080 (UI scale 1) and 2560x1440 (UI scale 2). Default: 800x600 only, retail's native size (several resolutions are a polish step at the end of the project)."),
    ], OptionScenes.Main);
}
